<script setup lang="ts">
import {ref,onMounted} from 'vue'
import CallAction from './CallAction.vue'
import IsolationStatistics from './IsolationStatistics.vue'
import IsolationProspectActivity from './IsolationProspectActivity.vue'
import IsolationVisits from './IsolationVisits.vue'
import IsolationBulkAssignment from './IsolationBulkAssignment.vue'
import IsolationDistribution from './IsolationDistribution.vue'
const showStatistics=ref(false)
const props=defineProps<{role:string;portal:(path:string,body?:any)=>Promise<any>;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const visitsOpen=ref(false),visitProspect=ref<number|undefined>(undefined)
const activity=ref<any>(null),commercialStatus=ref(''),dueOnly=ref(false),callbacksDue=ref(0)
const rows=ref<any[]>([]),count=ref(0),page=ref(1),search=ref(''),owner=ref(''),busy=ref(false),error=ref(''),selected=ref<any>(null),reason=ref('')
const people=ref<any[]>([]),peoplePage=ref(1),peopleCount=ref(0),peopleSearch=ref(''),target=ref(''),history=ref<any>(null),historyPage=ref(1),historyCount=ref(0),historyRows=ref<any[]>([])
async function run(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function load(){const data=await props.request(`work-queue/?page=${page.value}&search=${encodeURIComponent(search.value)}&owner=${encodeURIComponent(owner.value)}&commercial_status=${encodeURIComponent(commercialStatus.value)}&due=${dueOnly.value}`);rows.value=data.results;count.value=data.count;callbacksDue.value=(await props.request('workspace-dashboard/')).callbacks_due}
async function directory(step=0){peoplePage.value=step?peoplePage.value+step:1;target.value='';const data=await props.portal(`isolation/setters/?page=${peoplePage.value}&search=${encodeURIComponent(peopleSearch.value)}`);people.value=data.results;peopleCount.value=data.count}
async function open(row:any){await run(async()=>{selected.value=await props.request(`work-queue/${row.id}/`);reason.value='';await directory()})}
async function assign(release=false){await run(async()=>{const row=selected.value;const body:any={revision:row.revision,reason:reason.value};if(!release)body.proof=(await props.portal('isolation/setters/',{prospect_id:row.id,setter_id:Number(target.value)})).proof;await props.request(`work-queue/${row.id}/${release?'unassign':'assign'}/`,body);selected.value=null;await load()})}
async function callIntent(row:any,id:string){
 const current=await props.request(`work-queue/${row.id}/`)
 return props.request(`work-queue/${row.id}/call-intent/`,{revision:current.revision,request_id:id})
}
async function loadHistory(){const data=await props.request(`work-queue/${history.value.id}/history/?page=${historyPage.value}`);historyRows.value=data.results;historyCount.value=data.count}
onMounted(()=>run(load))
</script>
<template><section><button class="secondary" @click="showStatistics=!showStatistics">{{showStatistics?'Masquer les statistiques':'Voir les statistiques'}}</button><IsolationStatistics v-if="showStatistics" :request="request"/><h3>{{role==='administrator'?'Affectations des prospects Isolation':'Mes prospects Isolation'}}</h3><p v-if="error" role="alert">{{error}}</p><p>La validité de format et l’état technique de la ligne ne prouvent pas qu’une personne décroche. Un appel nécessite une confirmation explicite ; aucune vérification Lookup n’est lancée automatiquement.</p><button class="secondary" :disabled="busy" @click="visitProspect=undefined;visitsOpen=true">Toutes les visites de mon périmètre</button><p v-if="callbacksDue" role="status">{{callbacksDue}} rappel(s) arrivé(s) à échéance dans votre périmètre.</p><form @submit.prevent="run(async()=>{page=1;await load()})"><label>Nom, téléphone ou référence<input v-model="search"></label><label v-if="role==='administrator'">Responsable<input v-model="owner" placeholder="Vide : tous ; unassigned : sans affectation ; ou identifiant setter"></label><label>Résultat commercial<select v-model="commercialStatus"><option value="">Tous</option><option value="to_contact">À contacter</option><option value="in_progress">En cours</option><option value="callback">À rappeler</option><option value="interested">Intéressé</option><option value="not_interested">Non intéressé</option><option value="unreachable">Non joint</option></select></label><label><input v-model="dueOnly" type="checkbox">Rappels à échéance uniquement</label><button class="secondary" :disabled="busy">Rechercher / actualiser</button></form><IsolationDistribution v-if="role==='administrator'" :rows="rows" :portal="portal" :request="request" @changed="run(load)"/><IsolationBulkAssignment v-if="role==='administrator'" :rows="rows" :portal="portal" :request="request" @changed="run(load)"/><article v-for="row in rows" :key="row.id"><h4>{{row.name||'Prospect sans nom'}}</h4><p>{{row.raw_phone}} · {{row.phone||'Sans numéro normalisé'}} · {{row.campaign.name}}</p><p>Référence : {{row.reference||'—'}} · Validité de format : {{row.validity}} · État technique : {{row.line_status}}</p><p>Setter : {{row.assigned_setter?.name||'Non affecté'}}</p><p>Qualification : {{row.commercial_label}} · Rappel : {{row.callback_at?new Date(row.callback_at).toLocaleString('fr-FR'):'Aucun'}}{{row.callback_due?' · À traiter':''}}</p><CallAction v-if="role==='setter'" workspace="isolation" :resource-id="row.id" :phone="row.phone||row.raw_phone" :portal="portal" :prepare="(id:string)=>callIntent(row,id)" :disabled="busy"/><button class="secondary" :disabled="busy" @click="activity=row">Ouvrir le suivi</button><button class="secondary" :disabled="busy" @click="visitProspect=row.id;visitsOpen=true">Visites / réserver</button><template v-if="role==='administrator'"><button class="secondary" :disabled="busy" @click="open(row)">Affecter / réattribuer</button><button class="secondary" :disabled="busy" @click="run(async()=>{history=row;historyPage=1;await loadHistory()})">Historique</button></template></article><p v-if="!rows.length">Aucun prospect dans votre périmètre.</p><p>{{count}} prospect(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="run(async()=>{page--;await load()})">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="run(async()=>{page++;await load()})">Suivant</button><IsolationVisits v-if="visitsOpen" :key="visitProspect||0" :prospect-id="visitProspect" :role="role" :portal="portal" :request="request" @close="visitsOpen=false" @changed="run(load)"/><IsolationProspectActivity v-if="activity" :key="activity.id" :prospect-id="activity.id" :request="request" @close="activity=null" @saved="run(load)"/><section v-if="selected&&role==='administrator'"><h4>Affectation : {{selected.name||selected.raw_phone}}</h4><form @submit.prevent="run(()=>directory())"><label>Rechercher un setter Isolation actif<input v-model="peopleSearch"></label><button class="secondary" :disabled="busy">Rechercher</button></form><form @submit.prevent="assign()"><label>Nouveau responsable<select v-model="target" required><option value="">Choisir un setter</option><option v-for="person in people" :key="person.id" :value="String(person.id)" :disabled="person.id===selected.assigned_setter?.id">{{person.name}}</option></select></label><p>{{peopleCount}} setter(s) · page {{peoplePage}}</p><button type="button" class="secondary" :disabled="busy||peoplePage===1" @click="run(()=>directory(-1))">Précédent</button><button type="button" class="secondary" :disabled="busy||peoplePage*25>=peopleCount" @click="run(()=>directory(1))">Suivant</button><label>Motif obligatoire<textarea v-model="reason" required maxlength="1000"></textarea></label><button class="primary" :disabled="busy||!target">Confirmer l’affectation</button><button type="button" class="secondary" :disabled="busy||!selected.assigned_setter||!reason.trim()" @click="assign(true)">Retirer l’affectation</button><button type="button" class="secondary" :disabled="busy" @click="selected=null">Fermer</button></form></section><section v-if="history"><h4>Historique d’affectation</h4><article v-for="entry in historyRows" :key="entry.id"><small>{{new Date(entry.created_at).toLocaleString('fr-FR')}}</small><pre>{{JSON.stringify(entry.metadata,null,2)}}</pre></article><button class="secondary" :disabled="busy||historyPage===1" @click="run(async()=>{historyPage--;await loadHistory()})">Précédent</button><button class="secondary" :disabled="busy||historyPage*25>=historyCount" @click="run(async()=>{historyPage++;await loadHistory()})">Suivant</button><button class="secondary" @click="history=null">Fermer l’historique</button></section></section></template>
